from __future__ import annotations

import argparse
import json
import secrets
import time
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from typing import Any
from urllib.parse import urlparse

from .config import ServerConfig
from .scheduler import Scheduler


class WakeHTTPServer(ThreadingHTTPServer):
    def __init__(self, server_address, RequestHandlerClass, cfg: ServerConfig):
        super().__init__(server_address, RequestHandlerClass)
        self.cfg = cfg
        self.scheduler = Scheduler(cfg)


class Handler(BaseHTTPRequestHandler):
    server: WakeHTTPServer

    def log_message(self, fmt: str, *args) -> None:
        print("%s - %s" % (self.log_date_time_string(), fmt % args))

    def do_GET(self) -> None:
        parsed = urlparse(self.path)
        if parsed.path == "/health":
            self._json(200, {"ok": True, "time": int(time.time())})
            return
        if parsed.path == "/v1/jobs":
            if not self._authorized():
                return
            self._json(200, {"jobs": self.server.scheduler.store.list()})
            return
        self._json(404, {"error": "not_found"})

    def do_POST(self) -> None:
        parsed = urlparse(self.path)
        if parsed.path == "/v1/claude/stop-failure":
            if not self._authorized():
                return
            payload = self._read_json()
            if payload is None:
                return
            if payload.get("error") != "rate_limit":
                self._json(202, {"ignored": True, "reason": "not_rate_limit"})
                return
            job = self.server.scheduler.schedule_from_payload(payload)
            self._json(201, {"job": job})
            return
        if parsed.path == "/v1/jobs/claim":
            if not self._authorized():
                return
            payload = self._read_json()
            if payload is None:
                return
            worker_id = str(payload.get("worker_id") or "worker")[:200]
            job = self.server.scheduler.store.claim_due(worker_id=worker_id)
            self._json(200, {"job": job})
            return
        if parsed.path.startswith("/v1/jobs/") and parsed.path.endswith("/complete"):
            if not self._authorized():
                return
            payload = self._read_json()
            if payload is None:
                return
            job_id = parsed.path.split("/")[3]
            try:
                job = self.server.scheduler.store.complete(
                    job_id=job_id,
                    lease_token=str(payload.get("lease_token") or ""),
                    success=bool(payload.get("success")),
                    result=dict(payload.get("result") or {}),
                    retry_delay_seconds=self.server.cfg.retry_delay_seconds,
                )
            except (KeyError, PermissionError) as exc:
                self._json(409, {"error": str(exc)})
                return
            self._json(200, {"job": job})
            return
        self._json(404, {"error": "not_found"})

    def _authorized(self) -> bool:
        expected = self.server.cfg.auth_token
        if not expected:
            return True
        header = self.headers.get("Authorization", "")
        token = ""
        if header.lower().startswith("bearer "):
            token = header[7:].strip()
        token = token or self.headers.get("X-Claude-Wake-Token", "")
        if secrets.compare_digest(token, expected):
            return True
        self._json(401, {"error": "unauthorized"})
        return False

    def _read_json(self) -> dict[str, Any] | None:
        try:
            length = int(self.headers.get("Content-Length", "0"))
        except ValueError:
            length = 0
        if length < 1 or length > 256 * 1024:
            self._json(413, {"error": "invalid_body_size"})
            return None
        try:
            return json.loads(self.rfile.read(length).decode("utf-8"))
        except json.JSONDecodeError:
            self._json(400, {"error": "invalid_json"})
            return None

    def _json(self, status: int, body: dict[str, Any]) -> None:
        data = json.dumps(body, separators=(",", ":"), default=str).encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(data)))
        self.end_headers()
        self.wfile.write(data)


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description="Claude Wake scheduler server")
    parser.add_argument("--config", default="config/server.json")
    args = parser.parse_args(argv)

    cfg = ServerConfig.from_file(args.config)
    httpd = WakeHTTPServer((cfg.host, cfg.port), Handler, cfg)
    httpd.scheduler.start_local_worker()
    print(f"claude-wake server listening on {cfg.host}:{cfg.port}")
    if not cfg.auth_token:
        print("warning: auth_token is empty; use only on trusted networks")
    try:
        httpd.serve_forever()
    except KeyboardInterrupt:
        pass
    finally:
        httpd.scheduler.stop()
        httpd.server_close()
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

