from __future__ import annotations

import json
import os
import socket
import sys
import time
from pathlib import Path
from urllib import request

from .config import ClientConfig


def main(argv: list[str] | None = None) -> int:
    del argv
    try:
        payload = json.loads(sys.stdin.read() or "{}")
    except json.JSONDecodeError:
        return 0
    if payload.get("error") != "rate_limit":
        return 0

    cfg = ClientConfig.from_file()
    payload.setdefault("client", {})
    if isinstance(payload["client"], dict):
        payload["client"].update(
            {
                "hostname": socket.gethostname(),
                "tmux_pane": os.getenv("TMUX_PANE", ""),
                "sent_at": int(time.time()),
            }
        )

    try:
        body = json.dumps(payload, separators=(",", ":")).encode("utf-8")
        req = request.Request(
            cfg.server_url + "/v1/claude/stop-failure",
            data=body,
            method="POST",
            headers={
                "Content-Type": "application/json",
                "Authorization": f"Bearer {cfg.auth_token}",
            },
        )
        with request.urlopen(req, timeout=cfg.request_timeout_seconds) as resp:
            _log(cfg.hook_log_path, f"scheduled {resp.status}: {resp.read(512)!r}")
    except Exception as exc:  # noqa: BLE001
        _log(cfg.hook_log_path, f"schedule failed: {exc!r}")
    return 0


def _log(path: str, line: str) -> None:
    try:
        target = Path(path).expanduser()
        target.parent.mkdir(parents=True, exist_ok=True)
        with open(target, "a", encoding="utf-8") as fh:
            fh.write(f"{int(time.time())} {line}\n")
    except OSError:
        pass


if __name__ == "__main__":
    raise SystemExit(main())

