from __future__ import annotations

import re
from dataclasses import dataclass
from datetime import datetime, timedelta, timezone
from zoneinfo import ZoneInfo, ZoneInfoNotFoundError


TZ_ALIASES = {
    "UTC": "UTC",
    "GMT": "UTC",
    "PT": "America/Los_Angeles",
    "PST": "America/Los_Angeles",
    "PDT": "America/Los_Angeles",
    "MT": "America/Denver",
    "MST": "America/Denver",
    "MDT": "America/Denver",
    "CT": "America/Chicago",
    "CST": "America/Chicago",
    "CDT": "America/Chicago",
    "ET": "America/New_York",
    "EST": "America/New_York",
    "EDT": "America/New_York",
}


@dataclass(frozen=True)
class ParseResult:
    resume_at: datetime
    source: str
    raw: str

    @property
    def epoch(self) -> int:
        return int(self.resume_at.timestamp())


def payload_text(payload: dict) -> str:
    pieces: list[str] = []
    for key in ("error_details", "last_assistant_message", "message", "error"):
        value = payload.get(key)
        if isinstance(value, str) and value:
            pieces.append(value)
    return "\n".join(pieces)


def parse_reset_time(
    text: str,
    *,
    now: datetime | None = None,
    default_timezone: str = "UTC",
    fallback_delay_seconds: int = 5 * 60 * 60,
) -> ParseResult:
    if now is None:
        now = datetime.now(timezone.utc)
    if now.tzinfo is None:
        now = now.replace(tzinfo=timezone.utc)
    text = text.strip()

    parsed = _parse_pipe_timestamp(text)
    if parsed is not None:
        return ParseResult(parsed, "pipe_timestamp", text)

    parsed = _parse_iso_datetime(text, default_timezone)
    if parsed is not None:
        return ParseResult(_future(parsed, now), "iso_datetime", text)

    parsed = _parse_relative(text, now)
    if parsed is not None:
        return ParseResult(parsed, "relative_duration", text)

    parsed = _parse_time_of_day(text, now, default_timezone)
    if parsed is not None:
        return ParseResult(parsed, "time_of_day", text)

    return ParseResult(
        now.astimezone(timezone.utc) + timedelta(seconds=fallback_delay_seconds),
        "fallback_delay",
        text,
    )


def _parse_pipe_timestamp(text: str) -> datetime | None:
    match = re.search(r"(?:limit|rate.?limit|usage)[^\n|]{0,80}\|(\d{10,13})\b", text, re.I)
    if not match:
        return None
    raw = match.group(1)
    epoch = int(raw)
    if len(raw) == 13:
        epoch = epoch / 1000
    return datetime.fromtimestamp(epoch, tz=timezone.utc)


def _parse_iso_datetime(text: str, default_timezone: str) -> datetime | None:
    match = re.search(
        r"\b(\d{4}-\d{2}-\d{2}[ T]\d{1,2}:\d{2}(?::\d{2})?"
        r"(?:\s?(?:Z|UTC|[+-]\d{2}:?\d{2}))?)\b",
        text,
        re.I,
    )
    if not match:
        return None
    raw = match.group(1).replace(" ", "T")
    raw = re.sub(r"UTC$", "+00:00", raw, flags=re.I)
    raw = re.sub(r"Z$", "+00:00", raw, flags=re.I)
    if re.search(r"[+-]\d{4}$", raw):
        raw = raw[:-2] + ":" + raw[-2:]
    try:
        dt = datetime.fromisoformat(raw)
    except ValueError:
        return None
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=_zone(default_timezone))
    return dt.astimezone(timezone.utc)


def _parse_relative(text: str, now: datetime) -> datetime | None:
    lower = text.lower()
    if not re.search(r"\b(in|after|retry)\b", lower):
        return None
    seconds = 0
    for value, unit in re.findall(
        r"(\d+)\s*(hours?|hrs?|h|minutes?|mins?|m|seconds?|secs?|s)\b",
        lower,
    ):
        number = int(value)
        if unit.startswith("h"):
            seconds += number * 3600
        elif unit.startswith("m"):
            seconds += number * 60
        else:
            seconds += number
    if seconds <= 0:
        return None
    return now.astimezone(timezone.utc) + timedelta(seconds=seconds)


def _parse_time_of_day(text: str, now: datetime, default_timezone: str) -> datetime | None:
    trigger = r"(?:reset|resets|will reset|try again|retry|available|renews|until)"
    match = re.search(
        trigger
        + r"[^\n.]{0,120}?\b(?:at|after|by)?\s*"
        + r"(\d{1,2})(?::(\d{2}))?\s*([ap]\.?\s*m\.?)?"
        + r"(?:\s*\(([^)]+)\))?"
        + r"(?:\s*\b([A-Z]{2,4})\b)?",
        text,
        re.I,
    )
    if not match:
        return None

    hour = int(match.group(1))
    minute = int(match.group(2) or "0")
    ampm = (match.group(3) or "").lower().replace(".", "").replace(" ", "")
    tz_name = (match.group(4) or match.group(5) or default_timezone).strip()

    if ampm == "pm" and hour < 12:
        hour += 12
    if ampm == "am" and hour == 12:
        hour = 0
    if hour > 23 or minute > 59:
        return None

    zone = _zone(tz_name)
    local_now = now.astimezone(zone)
    candidate = local_now.replace(hour=hour, minute=minute, second=0, microsecond=0)
    if candidate <= local_now + timedelta(seconds=5):
        candidate += timedelta(days=1)
    return candidate.astimezone(timezone.utc)


def _future(value: datetime, now: datetime) -> datetime:
    value = value.astimezone(timezone.utc)
    if value <= now.astimezone(timezone.utc):
        return now.astimezone(timezone.utc)
    return value


def _zone(name: str):
    cleaned = name.strip()
    cleaned = TZ_ALIASES.get(cleaned.upper(), cleaned)
    try:
        return ZoneInfo(cleaned)
    except ZoneInfoNotFoundError:
        return ZoneInfo("UTC")

