from __future__ import annotations

import json
import time
from typing import Any
from urllib import error, parse, request

from .config import ServerConfig


def run_sprite_resume(cfg: ServerConfig, job: dict[str, Any]) -> tuple[bool, dict[str, Any]]:
    sprite_name = _sprite_name(cfg, job)
    if not sprite_name:
        return False, {"error": "sprite_name is missing"}
    if not cfg.sprite_api_token:
        return False, {"error": f"{cfg.sprite_api_token_env} is missing"}

    started = int(time.time())
    req = build_sprite_exec_request(cfg, job, sprite_name)
    try:
        with request.urlopen(req, timeout=cfg.sprite_exec_timeout_seconds) as resp:
            body = resp.read().decode("utf-8", errors="replace")
            parsed = _json_or_text(body)
            return True, {
                "backend": "sprite_exec",
                "sprite_name": sprite_name,
                "status": resp.status,
                "response": parsed,
                "started_at": started,
                "finished_at": int(time.time()),
            }
    except error.HTTPError as exc:
        body = exc.read().decode("utf-8", errors="replace")
        return False, {
            "backend": "sprite_exec",
            "sprite_name": sprite_name,
            "status": exc.code,
            "error": body[-4000:],
            "started_at": started,
            "finished_at": int(time.time()),
        }
    except Exception as exc:  # noqa: BLE001
        return False, {
            "backend": "sprite_exec",
            "sprite_name": sprite_name,
            "error": repr(exc),
            "started_at": started,
            "finished_at": int(time.time()),
        }


def build_sprite_exec_request(cfg: ServerConfig, job: dict[str, Any], sprite_name: str):
    params: list[tuple[str, str]] = []
    for arg in _sprite_command(cfg, job):
        params.append(("cmd", arg))
    cwd = str(job.get("cwd") or "")
    if cwd:
        params.append(("dir", cwd))

    base = cfg.sprite_api_base_url.rstrip("/")
    encoded_name = parse.quote(sprite_name, safe="")
    url = f"{base}/v1/sprites/{encoded_name}/exec?{parse.urlencode(params)}"
    return request.Request(
        url,
        data=b"",
        method="POST",
        headers={"Authorization": f"Bearer {cfg.sprite_api_token}"},
    )


def _sprite_command(cfg: ServerConfig, job: dict[str, Any]) -> list[str]:
    session_id = str(job.get("session_id") or "")
    prompt = str(job.get("prompt") or "continue")
    if not cfg.sprite_exec_detach:
        return ["claude", "-p", "--resume", session_id, prompt]

    script = r"""
set -euo pipefail
session_id="$1"
prompt="$2"
job_id="$3"
mkdir -p "$HOME/.cache/claude-wake"
log="$HOME/.cache/claude-wake/resume-${job_id}.log"
nohup claude -p --resume "$session_id" "$prompt" >> "$log" 2>&1 < /dev/null &
echo "claude-wake started pid=$! log=$log"
""".strip()
    return ["bash", "-lc", script, "claude-wake", session_id, prompt, str(job.get("id") or "job")]


def _sprite_name(cfg: ServerConfig, job: dict[str, Any]) -> str:
    if cfg.sprite_name:
        return cfg.sprite_name
    payload = job.get("payload") or {}
    if not isinstance(payload, dict):
        return ""
    client = payload.get("client") or {}
    if isinstance(client, dict) and client.get("sprite_name"):
        return str(client["sprite_name"])
    if payload.get("sprite_name"):
        return str(payload["sprite_name"])
    return ""


def _json_or_text(body: str) -> Any:
    try:
        return json.loads(body)
    except json.JSONDecodeError:
        return body[-4000:]

