from __future__ import annotations

import json
import subprocess


def sprite_info() -> dict[str, str]:
    try:
        proc = subprocess.run(
            ["sprite-env", "info"],
            text=True,
            stdout=subprocess.PIPE,
            stderr=subprocess.DEVNULL,
            timeout=2,
            check=False,
        )
    except Exception:  # noqa: BLE001
        return {}
    if proc.returncode != 0:
        return {}
    try:
        data = json.loads(proc.stdout)
    except json.JSONDecodeError:
        return {}
    return {
        "sprite_name": str(data.get("sprite_name") or ""),
        "sprite_id": str(data.get("sprite_id") or ""),
        "sprite_url": str(data.get("sprite_url") or ""),
    }

