from __future__ import annotations

import json
import os
from pathlib import Path
from typing import Any

from .sprite_env import sprite_info


def claude_project_dir(cwd: str) -> Path:
    normalized = os.path.abspath(os.path.expanduser(cwd))
    slug = "".join(ch if ch.isalnum() else "-" for ch in normalized)
    return Path("~/.claude/projects").expanduser() / slug


def find_latest_transcript(cwd: str) -> Path:
    project_dir = claude_project_dir(cwd)
    candidates = list(project_dir.glob("*.jsonl"))
    if not candidates:
        raise FileNotFoundError(f"no Claude transcripts found under {project_dir}")
    return max(candidates, key=lambda path: path.stat().st_mtime)


def payload_from_transcript(path: str | Path, cwd: str | None = None) -> dict[str, Any]:
    transcript = Path(path).expanduser()
    last_obj: dict[str, Any] = {}
    last_rate_limit: dict[str, Any] | None = None
    with open(transcript, "r", encoding="utf-8", errors="replace") as fh:
        for line in fh:
            if not line.strip():
                continue
            try:
                obj = json.loads(line)
            except json.JSONDecodeError:
                continue
            if isinstance(obj, dict):
                last_obj = obj
                if obj.get("error") == "rate_limit":
                    last_rate_limit = obj

    source = last_rate_limit or last_obj
    session_id = (
        source.get("sessionId")
        or source.get("session_id")
        or transcript.stem
    )
    source_cwd = cwd or source.get("cwd") or ""
    message_text = _message_text(source)
    payload: dict[str, Any] = {
        "hook_event_name": "StopFailure",
        "error": "rate_limit" if last_rate_limit else str(source.get("error") or "unknown"),
        "error_details": message_text,
        "last_assistant_message": message_text,
        "session_id": str(session_id),
        "cwd": str(source_cwd),
        "transcript_path": str(transcript),
        "client": sprite_info(),
        "manual": True,
    }
    if last_rate_limit:
        payload["timestamp"] = last_rate_limit.get("timestamp")
    return payload


def _message_text(obj: dict[str, Any]) -> str:
    message = obj.get("message")
    if isinstance(message, dict):
        parts: list[str] = []
        content = message.get("content")
        if isinstance(content, list):
            for item in content:
                if isinstance(item, dict) and isinstance(item.get("text"), str):
                    parts.append(item["text"])
                elif isinstance(item, str):
                    parts.append(item)
        elif isinstance(content, str):
            parts.append(content)
        if parts:
            return "\n".join(parts)
    for key in ("last_assistant_message", "error_details", "error"):
        value = obj.get(key)
        if isinstance(value, str) and value:
            return value
    return ""

