from __future__ import annotations

import json
import tempfile
import unittest
from pathlib import Path

from claude_wake.transcripts import claude_project_dir, payload_from_transcript


class TranscriptTests(unittest.TestCase):
    def test_project_dir_slug_matches_claude_storage(self):
        self.assertEqual(
            claude_project_dir("/home/sprite/type"),
            Path("~/.claude/projects/-home-sprite-type").expanduser(),
        )

    def test_payload_from_rate_limit_transcript(self):
        with tempfile.TemporaryDirectory() as tmp:
            transcript = Path(tmp) / "session-123.jsonl"
            entries = [
                {
                    "type": "assistant",
                    "sessionId": "session-123",
                    "cwd": "/home/sprite/type",
                    "message": {"content": [{"type": "text", "text": "working"}]},
                },
                {
                    "type": "assistant",
                    "sessionId": "session-123",
                    "cwd": "/home/sprite/type",
                    "timestamp": "2026-07-01T23:53:38.770Z",
                    "error": "rate_limit",
                    "message": {
                        "content": [
                            {
                                "type": "text",
                                "text": "You've hit your session limit · resets 3:10am (UTC)",
                            }
                        ]
                    },
                },
            ]
            transcript.write_text("\n".join(json.dumps(e) for e in entries), encoding="utf-8")
            payload = payload_from_transcript(transcript)
            self.assertEqual(payload["error"], "rate_limit")
            self.assertEqual(payload["session_id"], "session-123")
            self.assertEqual(payload["cwd"], "/home/sprite/type")
            self.assertIn("resets 3:10am", payload["last_assistant_message"])
            self.assertTrue(payload["manual"])


if __name__ == "__main__":
    unittest.main()

