from __future__ import annotations

from typing import Any


VALID_KINDS = {"claude", "codex", "crush"}


def resume_kind(job: dict[str, Any]) -> str:
    payload = job.get("payload") or {}
    if isinstance(payload, dict):
        kind = str(payload.get("resume_kind") or payload.get("tool") or "claude").lower()
    else:
        kind = "claude"
    return kind if kind in VALID_KINDS else "claude"


def resume_argv(kind: str, session_id: str, prompt: str) -> list[str]:
    if kind == "codex":
        if session_id and session_id not in {"latest", "unknown"}:
            return ["codex", "exec", "resume", session_id, prompt]
        return ["codex", "exec", "resume", "--last", prompt]
    if kind == "crush":
        if session_id and session_id not in {"latest", "unknown"}:
            return ["crush", "run", "--session", session_id, prompt]
        return ["crush", "run", "--continue", prompt]
    return ["claude", "-p", "--resume", session_id, prompt]

